using System;using System.Collections.Generic;using BeamScheduleFormatter;
class ProgramOfWorksTests {
 static int checks;static void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}static void Near(double a,double b,string m){Check(Math.Abs(a-b)<.0000001,m);}
 static void Main(){var door=new OpeningItem{Id="D1",Description="Wood door",Wall="W1",Material="Wood",Kind="Door",Width=1,Height=2.1,Quantity=2,JambDepth=.15,JambThickness=.05,LeafThickness=.04,Faces=2,LocksPerUnit=1,HingesPerUnit=3};door.Validate();Near(door.Area,4.2,"Overall opening quantity");Near(door.LeafWidth,.9,"Jamb deducted from leaf width");Near(door.LeafHeight,2.05,"Door top jamb deducted");Near(door.LeafPaint,7.911,"Both leaf faces and edges");Near(door.JambPaint,2.6,"Door jamb three sides");Check(door.Locks==2&&door.Hinges==6,"Hardware multiplied once");
 var window=new OpeningItem{Id="AW1",Description="Aluminum window",Wall="w1",Material="Aluminum",Kind="Window",Width=1.2,Height=1,Quantity=1,LocksPerUnit=0,HingesPerUnit=0};window.Validate();Near(window.LeafPaint+window.JambPaint,0,"Aluminum paint excluded");var wall=new WallItem{Id="W1",Description="Wall",Length=5,Height=3,Quantity=2,BlockWidth=.4,BlockHeight=.2};{var areaWall=new WallItem{Id="WA",Description="Area wall",EnteredArea=20,Quantity=3,BlockWidth=.4,BlockHeight=.2};Near(areaWall.Gross,60,"Gross area input is multiplied by Wall Qty");}{var typed=new FinishItem{Id="T",Description="Typed",Code="F",Category="Wall",Wall="",Kind="Tiles",Side="A",Basis="Dimensions",TypedArea=5,Quantity=2};Near(typed.Total(null,new OpeningItem[0]),10,"Typed finish area x Qty, no Wall ID");var adj=new FinishItem{Id="A",Description="Adjust",Code="F",Category="Wall",Wall="",Kind="Tiles",Side="A",Basis="Dimensions",TypedArea=-3.5,Quantity=1};Near(adj.Total(null,new OpeningItem[0]),-3.5,"Negative typed area is an adjustment");var bad=new FinishItem{Id="B",Description="Bad",Code="F",Category="Wall",Wall="W1",Kind="Tiles",Side="A",Basis="Dimensions",TypedArea=-1,Quantity=1};bool refused=false;try{bad.Validate();}catch(Exception){refused=true;}Check(refused,"An adjustment needs a blank Wall ID");}var list=new[]{door,window};Near(wall.Gross,30,"Wall group quantity");Near(wall.Deduction(list),5.4,"Wood + aluminum deduction once, case-insensitive");Near(wall.Net(list),24.6,"Net area");Check(wall.Blocks(list)==308,"Ceiling whole blocks");window.Wall="OTHER";Near(wall.Deduction(list),4.2,"Other walls not deducted");door.Quantity=100;bool rejected=false;try{wall.Net(list);}catch{rejected=true;}Check(rejected,"Excess opening area rejected");door.Quantity=1;door.Width=.05;rejected=false;try{door.Validate();}catch{rejected=true;}Check(rejected,"Impossible jamb/leaf dimensions rejected");/* v1.50.16: aluminum doors and windows have no lockset / hinges ("no locket hinges if aluminum") */
{var ad=new OpeningItem{Id="AD1",Description="Aluminum door",Wall="w1",Material="Aluminum",Kind="Door",Width=0.9,Height=2.1,Quantity=2,LocksPerUnit=1,HingesPerUnit=3};ad.Validate();if(ad.Locks!=0||ad.Hinges!=0)throw new Exception("Aluminum door has no lockset / hinges");checks++;
 var aw=new OpeningItem{Id="AW2",Description="Aluminum casement",Wall="w1",Material="Aluminum",Kind="Window",Width=1.2,Height=1.2,Quantity=3,LocksPerUnit=2,HingesPerUnit=4,Operation="Swing"};aw.Validate();if(aw.Locks!=0||aw.Hinges!=0)throw new Exception("Aluminum window has no lockset / hinges");checks++;
 foreach(var m in new[]{"Wood","PVC","Steel"}){var d=new OpeningItem{Id="D-"+m,Description=m+" door",Wall="w1",Material=m,Kind="Door",Width=0.9,Height=2.1,Quantity=2,JambThickness=m=="Wood"?0.05:0,JambDepth=m=="Wood"?0.15:0};if(d.Locks!=2||d.Hinges<4)throw new Exception(m+" door keeps its lockset and hinges");checks++;}}
/* v5.0.19: "(No Top Coat)" is not shown; the stored description is unchanged */
if(PayItemText.Display("Masonary/Concrete Painting Works (No Top Coat)")!="Masonary/Concrete Painting Works"||PayItemText.Display("Masonary Painting Works (Skim Coat)")!="Masonary Painting Works (Skim Coat)")throw new Exception("(No Top Coat) hidden from pay-item text");checks++;
{var t=new BackupTarget{Code="1032(1)a",Description="Masonary/Concrete Painting Works (No Top Coat)",Unit="sq.m.",Row=1592};if(t.Caption.Contains("No Top Coat")||!BackupMapping.Identity(t).Contains("NOTOPCOAT")&&BackupMapping.Identity(t)==BackupMapping.Identity(new BackupTarget{Code="1032(1)a",Description="Masonary/Concrete Painting Works",Unit="sq.m.",Row=1592}))throw new Exception("caption hides it, mapping identity keeps the stored text");checks++;}
Console.WriteLine("PASS: "+checks+" door/window paint, jamb, hardware, linked wall deductions and block takeoff checks.");}
}
